#include "ntasm.h"
#include <stdio.h>
#include <string.h>
static unsigned checks,failures;
#define CHECK(c,m) do{checks++;if(!(c)){failures++;fprintf(stderr,"FAIL %s\n",m);}}while(0)
static int contains(const uint8_t*b,size_t n,const uint8_t*p,size_t pn){if(pn>n)return 0;for(size_t i=0;i+pn<=n;i++)if(!memcmp(b+i,p,pn))return 1;return 0;}
int main(void){const char*valid="module m\ntarget x86_64-nexora-uefi\nsection .text {\nexport fn main()->u64\neffects {}\nclobbers {} {\ncall_indirect rax\nreturn 0\n}\n}\n";NtArtifact artifact={0};int ok=nt_compile(valid,strlen(valid),&artifact);if(!ok)fprintf(stderr,"VALID E%u %zu:%zu %s\\n",artifact.error.code,artifact.error.line,artifact.error.column,artifact.error.message);CHECK(ok,"valid indirect call compiles");const uint8_t bytes[]={0xff,0xd0};CHECK(ok&&contains(artifact.text.bytes,artifact.text.size,bytes,sizeof bytes),"call rax bytes");nt_artifact_free(&artifact);const char*width="module m\ntarget x86_64-nexora-uefi\nsection .text {\nexport fn main()->u64\neffects {}\nclobbers {} {\ncall_indirect eax\nreturn 0\n}\n}\n";artifact=(NtArtifact){0};ok=nt_compile(width,strlen(width),&artifact);if(ok||artifact.error.code!=400)fprintf(stderr,"WIDTH ok%d E%u %zu:%zu %s\\n",ok,artifact.error.code,artifact.error.line,artifact.error.column,artifact.error.message);CHECK(!ok&&artifact.error.code==400,"32-bit target rejected");nt_artifact_free(&artifact);const char*arity="module m\ntarget x86_64-nexora-uefi\nsection .text {\nexport fn main()->u64\neffects {}\nclobbers {} {\ncall_indirect rax,rbx\nreturn 0\n}\n}\n";artifact=(NtArtifact){0};ok=nt_compile(arity,strlen(arity),&artifact);if(ok||artifact.error.code!=400)fprintf(stderr,"ARITY ok%d E%u %zu:%zu %s\\n",ok,artifact.error.code,artifact.error.line,artifact.error.column,artifact.error.message);CHECK(!ok&&artifact.error.code==400,"arity rejected");nt_artifact_free(&artifact);printf("NTASM_INDIRECT_CALL checks=%u failures=%u\n",checks,failures);return failures?1:0;}
